"'$reader = [System.IO.StreamReader]::new($path)
$types = @{}
$lineCount = 0
while ($null -ne ($line = $reader.ReadLine())) {
    $lineCount++
    try { $obj = $line | ConvertFrom-Json -ErrorAction Stop } catch { continue }
    $t = $obj.type
    if (-not $types.ContainsKey($t)) { $types[$t] = 0 }
    $types[$t]++
    if ($t -eq "response_item") {
        $pt = $obj.payload.type
        $key = "resp.$pt"
        if (-not $types.ContainsKey($key)) { $types[$key] = 0 }
        $types[$key]++
    }
}
$reader.Close()
"Total lines: $lineCount"
$types.GetEnumerator() | Sort-Object Name | ForEach-Object { "$($_.Key): $($_.Value)" }'

