"'$kw = @("headless_wave","lifecycle_supervisor","terminal_packet_epilogue","orchestration_epilogue","epilogue")
$idx = 0
Get-Content $path | ForEach-Object {
    $idx++
    try { $obj = $_ | ConvertFrom-Json -ErrorAction Stop } catch { return }
    if ($obj.type -ne "response_item") { return }
    $p = $obj.payload
    if ($p.type -eq "custom_tool_call" -or $p.type -eq "function_call") {
        $s = $_
        foreach ($k in $kw) {
            if ($s -match $k) {
                $inp = ""
                if ($p.input) { $inp = [string]$p.input } elseif ($p.arguments) { $inp = [string]$p.arguments }
                if ($inp.Length -gt 300) { $inp = $inp.Substring(0,300) + "..." }
                Write-Output ("[" + $obj.timestamp + "] " + $p.type + " name=" + $p.name + " :: " + $inp)
                break
            }
        }
    }
}'

